      cancelled: ['❌ Отменено: {title}', '{when}'], reactivated: ['Снова в силе: {title}', '{when}'],
      changed: ['Изменения: {title}', '{when}'],
      newEvent: ['Новая тренировка: {title}', '{when} — ответьте, пожалуйста'], newEvents: ['Новые тренировки ({n}): {title}', 'С {when}, еженедельно — ответьте, пожалуйста'],
      msg: ['💬 {name}', '{text}'], news: ['{heading}', '{text}'], toCoach: ['✉️ {name}', '{text}'],
